  const e = eyeAt(z);
  const bob = 0.05 * Math.sin(f.time * 1.3);
  app.camera?.setPose(
    { position: [e.pos[0], e.pos[1] + bob, e.pos[2]], target: e.look, fov: 58, near: 0.3, far: 700 },
    { cut: true }
  );
  if (!ready) {
    ready = true;
    (window as unknown as { __EVAL_READY__?: boolean }).__EVAL_READY__ = true;
  }
});
void app.ready();

